 const storageScope=workspaceScope(session?.user?.id,config.apiUrl),[reportListView,setReportListView]=useWorkspaceState('reportView',null,storageScope);
 useEffect(()=>{try{localStorage.removeItem('so-lieu.demo.v1');}catch{}},[]);
 function clearSession(){epoch.current++;windowSeq.current++;windowKey.current='';sessionRef.current=null;dbRef.current=null;clearRequestState();setWindowError('');forgetSession();try{localStorage.removeItem('so-lieu.ui-user');}catch{}setSession(null);setDb(null);dirtyReport.current=false;setError('');}
 function handleAccessError(e){if(e.code==='FORBIDDEN'){try{localStorage.removeItem('so-lieu.ui-user');}catch{}setAccessError('Không đủ quyền để thực hiện.');if(!dbRef.current)setError('Không đủ quyền để tải dữ liệu. Bấm Thử lại để tải theo quyền tài khoản hiện tại.');return true;}if(e.code!=='UNAUTHENTICATED')return false;clearSession();setAccessError('Phiên đăng nhập không còn hợp lệ. Vui lòng đăng nhập lại.');return true;}
 const [db,setDb]=useState(null),[mobile,setMobile]=useState(false),[toast,setToast]=useState(null),[loading,setLoading]=useState(false),[error,setError]=useState('');
