 useEffect(()=>{const id=db?.viewer?.id;if(session&&id&&id!==session.user.id){const next={token:session.token,user:{id}};persistSession(next);sessionRef.current=next;setSession(next);}},[db?.viewer?.id,session?.user?.id]);
 useEffect(()=>{if(route.focus&&db){const prefix=page==='products'?'product-':page==='accounts'?'account-':null;if(prefix)document.getElementById(prefix+route.focus)?.scrollIntoView({block:'center',behavior:'smooth'});}},[page,route.focus,db?.products,db?.accounts]);
