function Targets({db,user,mutate,notify,route}){
 const [month,setMonth]=useWorkspaceState('targets.month.'+(route?.focus||'all'),route?.month||(user.role==='admin'?previousDay():dayString()).slice(0,7)),[account,setAccount]=useWorkspaceState('targets.account.'+(route?.focus||'all'),user.role==='admin'?(route?.accountId||db.accounts.find(a=>isEmployee(a))?.id):user.id),[editing,setEditing]=useWorkspaceState('targets.editing.'+(route?.focus||'all'),false),[draft,setDraft]=useWorkspaceState('targets.draft.'+(route?.focus||'all'),[]),[salary,setSalary]=useWorkspaceState('targets.salary.'+(route?.focus||'all'),0);
 const previousPeriod=useRef(month+'|'+account);useEffect(()=>{const next=month+'|'+account;if(previousPeriod.current!==next){setEditing(false);previousPeriod.current=next;}},[month,account]);
 const accountTargets=db.targets.filter(t=>t.accountId===account&&t.month===month).sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''));
 const saleTarget=db.accounts.find(a=>a.id===account)?.role==='sale';
 const targetDb=saleTarget?saleOrderDb(db):db;
 const summary=summarizeTargets(targetDb,account,month);
 const products=summary.rows.map(r=>r.product);
 const sum={total:summary.total};
 const totalGoal=summary.total.goal,careGoal=summary.total.careGoal;
 function edit(){setDraft(products.filter(p=>user.role==='admin'?summary.rows.find(r=>r.product.id===p.id)?.editable:p.active&&db.assignments.some(a=>a.active&&a.accountId===user.id&&a.productId===p.id)).map(p=>{const t=accountTargets.find(t=>t.productId===p.id);return {productId:p.id,revision:t?.revision||0,revenue:t?.revenue||0,care:t?.care||0};}));setSalary(accountTargets[0]?.salary||0);setEditing(true);}
 return <><Heading eyebrow="KẾ HOẠCH & TIẾN ĐỘ" title="Mục tiêu tháng" description="">{<ActionButton className="btn primary" disabled={!containsRange(db.scope,periodRange('month','','','',month))} onClick={edit}><Pencil size={16}/> Nhập / Sửa mục tiêu</ActionButton>}</Heading><div className="panel entry-toolbar"><label>Tháng mục tiêu<DateField type="month" value={month} onChange={e=>setMonth(e.target.value)}/></label>{user.role==='admin'&&<label>Account<select value={account} onChange={e=>setAccount(e.target.value)}>{db.accounts.filter(a=>isEmployee(a)).map(a=><option key={a.id} value={a.id}>{accountLabel(a)}</option>)}</select></label>}<div className="entry-meta"><b>{db.accounts.find(a=>a.id===account)?.ownerName}</b><span>Giá được giữ theo kỳ mục tiêu đã lưu</span></div></div><WindowGate range={periodRange('month','','','',month)}><div className="stats three" style={saleTarget?{gridTemplateColumns:'repeat(2,minmax(0,1fr))'}:undefined}><article className="stat"><div className="stat-top">Mục tiêu lương <Wallet size={18}/></div><div className="stat-value">{money(accountTargets[0]?.salary||0)}<small>đ</small></div></article><article className="stat"><div className="stat-top">Mục tiêu doanh thu <Target size={18}/></div><div className="stat-value">{money(totalGoal)}<small>đ</small></div><div className="progress-track"><i style={{width:Math.min(100,divide(sum.total.revenue,totalGoal)*100)+'%'}}/></div><div className="stat-sub">Đã đạt {pct(divide(sum.total.revenue,totalGoal))} · {money(sum.total.revenue)}đ</div></article>{!saleTarget&&<article className="stat"><div className="stat-top">Mục tiêu doanh thu chăm <MessageSquare size={18}/></div><div className="stat-value">{money(careGoal)}<small>đ</small></div><div className="progress-track purple-track"><i style={{width:Math.min(100,divide(sum.total.care,careGoal)*100)+'%'}}/></div><div className="stat-sub">Đã đạt {pct(divide(sum.total.care,careGoal))} · {money(sum.total.care)}đ</div></article>}</div><div className="panel"><div className="panel-heading"><div><h2>Từ mục tiêu đến kết quả</h2><p>Số đơn làm tròn lên · Chia đúng số ngày thực tế trong tháng</p></div><span className="tag">{products.length} sản phẩm</span></div><TargetsTable summary={summary} sale={saleTarget} focusProduct={db.targets.find(t=>t.id===route?.focus)?.productId}/></div>
 {editing&&<Modal title="Đặt mục tiêu tháng" onClose={()=>setEditing(false)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveTargets',{month,accountId:account,targets:draft,salary})){setEditing(false);setDraft([]);notify('Đã lưu mục tiêu tháng.');}}}><label>Mục tiêu lương (VNĐ)<NumberField type="number" min="0" value={salary} onChange={e=>setSalary(Number(e.target.value))}/></label><p className="muted">Chỉ nhập các mức doanh thu. Giá và số đơn được tính từ danh mục sản phẩm.</p>{draft.map((t,i)=><div className="target-edit-row" key={t.productId}><b>{db.products.find(p=>p.id===t.productId)?.name}</b><label>Mục tiêu doanh thu<NumberField type="number" min="0" required value={t.revenue} onChange={e=>setDraft(draft.map((x,j)=>j===i?{...x,revenue:Number(e.target.value)}:x))}/></label>{!saleTarget&&<label>Mục tiêu chăm<NumberField type="number" min="0" required value={t.care} onChange={e=>setDraft(draft.map((x,j)=>j===i?{...x,care:Number(e.target.value)}:x))}/></label>}</div>)}<div className="modal-actions"><ActionButton className="btn" type="button" onClick={()=>setEditing(false)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu mục tiêu</ActionButton></div></ActionForm></Modal>}
 </WindowGate></>
}
function Products({db,mutate,notify,route}){const [form,setForm]=useWorkspaceState('products.form.'+(route?.focus||'all'),null),[batch,setBatch]=useWorkspaceState('products.batchOpen',false);return <><Heading eyebrow="QUẢN TRỊ" title="Sản phẩm & giá bán" description=""><ActionButton className="btn primary" onClick={()=>{if(window.matchMedia('(min-width: 769px)').matches)setBatch(true);else setForm({name:'',priceUsd:'',rate:22500,active:true,color:'#18765c',accountIds:[]});}}><Plus size={17}/> Thêm sản phẩm</ActionButton></Heading><div className="product-grid">{db.products.map(p=><article id={'product-'+p.id} className={'panel product-card '+(route?.focus===p.id?'notification-focus':'')} key={p.id}><div className="product-card-top"><span className="product-mark" style={{background:p.color||'#18765c'}}>{p.name[0]}</span><span className={'status '+(p.active?'done':'draft')}>{p.active?'Đang sử dụng':'Ngừng dùng'}</span></div><h2>{p.name}</h2><div className="product-price">${money(p.priceUsd)}<small>{money(p.priceUsd*p.rate)}đ</small></div><p className="muted">Tỷ giá: {money(p.rate)}đ / USD</p><div className="product-card-foot"><span><Users size={15}/> {db.assignments.filter(a=>a.productId===p.id&&a.active).length} account</span><ActionButton className="text-btn" onClick={()=>setForm({...p})}>Chỉnh sửa <ArrowUpRight size={14}/></ActionButton></div></article>)}</div>{form&&<Modal title={form.id?'Chỉnh sửa sản phẩm':'Thêm sản phẩm'} onClose={()=>setForm(null)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveProduct',form)){setForm(null);notify('Đã lưu sản phẩm.');}}}><div className="form-grid"><label>Tên sản phẩm<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Giá USD<NumberField required type="number" step="0.01" min="0.01" value={form.priceUsd} onChange={e=>setForm({...form,priceUsd:Number(e.target.value)})}/></label><label>Tỷ giá<NumberField required type="number" min="1" value={form.rate} onChange={e=>setForm({...form,rate:Number(e.target.value)})}/></label><label>Trạng thái<select value={String(form.active)} onChange={e=>setForm({...form,active:e.target.value==='true'})}><option value="true">Đang sử dụng</option><option value="false">Ngừng sử dụng</option></select></label></div><>{!form.id&&<EmployeePicker accounts={db.accounts} value={form.accountIds||[]} onChange={ids=>setForm({...form,accountIds:ids})}/>}</><div className="calc-result"><span>Giá VNĐ</span><b>{money(form.priceUsd*form.rate)}đ</b></div><div className="modal-actions"><ActionButton className="btn" type="button" onClick={()=>setForm(null)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu sản phẩm</ActionButton></div></ActionForm></Modal>}{batch&&<BatchEntry kind="products" accounts={db.accounts} mutate={mutate} notify={notify} onClose={()=>setBatch(false)}/>}</>}
function Accounts({db,mutate,notify,route}){const [form,setForm]=useWorkspaceState('accounts.form.'+(route?.focus||'all'),null),[deleting,setDeleting]=useState(null),[archived,setArchived]=useState(false);
 const [assignmentDraft,setAssignmentDraft,assignmentDraftMeta]=useWorkspaceState('accounts.assignmentChanges',[]);
 const conflicts=assignmentDraft.filter(row=>assignmentConflict(row,db.assignments));
 async function saveAssignments(){if(await mutate('assignBulk',{changes:assignmentDraft})){assignmentDraftMeta.clear();notify('Đã lưu toàn bộ phân phối sản phẩm.');}}
 return <><Heading eyebrow="QUẢN TRỊ" title="Account & phân phối" description="Giao đúng sản phẩm cho đúng người. Dữ liệu của mỗi account được tách riêng."><ActionButton className="btn primary" onClick={()=>setForm({ownerName:'',username:'',password:'',role:'user'})}><Plus size={17}/> Tạo account</ActionButton></Heading><section className="panel"><div className="panel-heading"><div><h2>Phân phối sản phẩm</h2><p>Bật/tắt các ô rồi bấm Lưu phân phối để gửi một lần.</p></div><label className="care-check"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/> Hiện user đã xóa</label></div><div className="assignment-savebar"><span>{assignmentDraft.length?assignmentDraft.length+' ô thay đổi chưa lưu':'Phân phối đã đồng bộ'}{assignmentDraft.length>0&&' · Giữ nội dung khi F5'}</span><div><ActionButton className="btn" disabled={!assignmentDraft.length} onClick={()=>assignmentDraftMeta.clear()}>Hủy thay đổi</ActionButton><ActionButton className="btn primary" disabled={!assignmentDraft.length||conflicts.length>0} onClick={saveAssignments}><Save size={16}/> Lưu phân phối{assignmentDraft.length>0?' ('+assignmentDraft.length+')':''}</ActionButton></div></div>{conflicts.length>0&&<p className="info-note">Có ô đã được cập nhật từ nơi khác. Hủy thay đổi để dùng bản mới, rồi chọn lại các ô cần sửa.</p>}<div className="table-scroll"><table className="assignment-table"><thead><tr><th>Chủ sở hữu / Account</th>{db.products.filter(p=>p.active).map(p=><th key={p.id}>{p.name}</th>)}</tr></thead><tbody>{db.accounts.filter(a=>archived||!a.deletedAt||route?.focus===a.id).map(a=><tr id={'account-'+a.id} key={a.id} className={route?.focus===a.id?'notification-focus':''}><td><span className="account-cell"><span className="avatar small-avatar">{a.ownerName[0]}</span><span><b>{a.ownerName}</b><small>@{a.username} · {a.role==='admin'?'Admin':a.role==='sale'?'SALE':'MKT'}</small></span>{a.deletedAt?<ActionButton className="btn" onClick={async()=>{if(await mutate('restoreAccount',{id:a.id}))notify('Đã khôi phục user. Giao lại sản phẩm để bắt đầu nhập liệu.');}}>Khôi phục</ActionButton>:<><ActionButton className="icon-btn" aria-label={'Sửa account '+a.ownerName} onClick={()=>setForm({...a,password:''})}><Pencil size={14}/></ActionButton>{isEmployee(a)&&<ActionButton className="icon-btn" aria-label={'Xóa user '+a.ownerName} onClick={()=>setDeleting(a)}><Trash2 size={14}/></ActionButton>}</>}</span></td>{a.deletedAt?<td colSpan={Math.max(1,db.products.filter(p=>p.active).length)} className="admin-access-cell">Đã xóa · Đã khóa đăng nhập</td>:a.role==='admin'?<td colSpan={Math.max(1,db.products.filter(p=>p.active).length)} className="admin-access-cell">Admin được xem tất cả sản phẩm</td>:db.products.filter(p=>p.active).map(p=>{const draft=assignmentDraft.find(x=>x.accountId===a.id&&x.productId===p.id);const active=draft?draft.active:db.assignments.some(x=>x.accountId===a.id&&x.productId===p.id&&x.active);return <td key={p.id} className={draft?'assignment-pending':''}><ActionButton role="switch" aria-checked={active} aria-label={a.ownerName+' — '+p.name} className={'switch '+(active?'on':'')} onClick={()=>setAssignmentDraft(current=>toggleAssignment(current,db.assignments,a.id,p.id))}><span/></ActionButton></td>})}</tr>)}</tbody></table></div><div className="table-note">Bấm biểu tượng bút để sửa account và vai trò. Admin cuối cùng không thể bị hạ quyền. Đổi role sẽ đăng xuất các phiên cũ của account đó.</div></section>{form&&<Modal title={form.id?'Chỉnh sửa account':'Tạo account mới'} onClose={()=>setForm(null)}><ActionForm onSubmit={async e=>{e.preventDefault();if(await mutate('saveAccount',form)){setForm(null);notify('Đã lưu account.');}}}><div className="form-grid"><label>Tên chủ sở hữu<input required value={form.ownerName} onChange={e=>setForm({...form,ownerName:e.target.value})}/></label><label>Tên đăng nhập<input required pattern="[a-zA-Z0-9_.-]+" value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/></label><label>Vai trò<select value={form.role||'user'} onChange={e=>setForm({...form,role:e.target.value})}><option value="user">MKT — chức năng hiện tại</option><option value="sale">SALE — báo cáo và đơn được phụ trách</option><option value="admin">Admin — quản lý toàn bộ</option></select></label><label>Mật khẩu {form.id?'mới (để trống nếu giữ nguyên)':''}<input type="password" autoComplete="new-password" required={!form.id} minLength={6} maxLength={20} value={form.password||''} onChange={e=>setForm({...form,password:e.target.value})}/></label></div><div className="modal-actions"><ActionButton type="button" className="btn" onClick={()=>setForm(null)}>Hủy</ActionButton><ActionButton className="btn primary">Lưu account</ActionButton></div></ActionForm></Modal>}{deleting&&<Modal title="Xóa user?" onClose={()=>setDeleting(null)}><p>Xóa tài khoản <b>{deleting.ownerName} (@{deleting.username})</b> sẽ khóa đăng nhập và thu hồi các phiên cũ. Báo cáo, đơn hàng và lịch sử vẫn được giữ.</p><div className="modal-actions"><ActionButton type="button" className="btn" onClick={()=>setDeleting(null)}>Hủy</ActionButton><ActionButton className="btn danger" onClick={async()=>{if(await mutate('deleteAccount',{id:deleting.id})){setDeleting(null);notify('Đã xóa user, dữ liệu lịch sử được giữ nguyên.');}}}>Xóa user</ActionButton></div></Modal>}</>}
function SettingsPage(){return <Heading title="Kết nối MongoDB" description="Backend Next.js dùng cấu hình phía server trong config/mongodb.js. Điền MONGODB_URI, MONGODB_DB và SL_AUTH_PEPPER trong môi trường triển khai. Không đặt bí mật trong frontend."/>;}
export default function Workspace(){return <OperationsProvider><App/></OperationsProvider>;}
